DROP TABLE IF EXISTS `evento`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `evento` (
  `evento_id` char(4) NOT NULL,
  `titulo` varchar(100) DEFAULT NULL,
  `nome` varchar(120) DEFAULT NULL,
  `tipo` tinyint DEFAULT NULL,
  `ano` int DEFAULT NULL,
  `menu` json DEFAULT NULL,
  `ativo` tinyint(1) NOT NULL DEFAULT '1',
  `finalizado` tinyint(1) NOT NULL DEFAULT '0',
  `spoilers` tinyint(1) NOT NULL DEFAULT '0',
  `tem_certificado` tinyint(1) NOT NULL DEFAULT '0',
  `presidente` varchar(45) DEFAULT NULL,
  `data` varchar(100) DEFAULT NULL,
  `mandato_presidente` varchar(9) DEFAULT NULL,
  `local` varchar(120) DEFAULT NULL,
  `em_andamento` tinyint(1) NOT NULL DEFAULT '0',
  `carga_horaria` int DEFAULT NULL,
  PRIMARY KEY (`evento_id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1;
